#define MAX_DETECTIONS 10

struct detection_box {
  float ymin;       // 归一化 0~1
  float xmin;       // 归一化 0~1
  float ymax;       // 归一化 0~1
  float xmax;       // 归一化 0~1
  float score;      // 置信度 0~1
  int class_id;     // 类别 ID (person=0)
};

struct detect_result {
  int num_detections;
  struct detection_box boxes[MAX_DETECTIONS];
};

int tflite_init(const char *model_path);
