/****************************************************************************
 * apps/examples/human_detect/camera_capture.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * USB Camera (UVC) capture module.  Handles V4L2 device setup, MJPEG
 * frame acquisition, and JPEG decoding to RGB565 via TJpgDec.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>

#include "camera_capture.h"
#include "tjpgd.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CAPTURE_BUF_COUNT  6  /* V4L2 user-pointer buffer count */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct v_buffer
{
  uint8_t *start;
  uint32_t length;
};

/* TJpgDec I/O device: wraps a memory buffer for input callback */

struct mjpeg_iodev_s
{
  const uint8_t *data;
  size_t         len;
  size_t         pos;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int                    g_cap_fd = -1;       /* V4L2 file descriptor */
static struct v_buffer       *g_buffers = NULL;     /* Capture buffers */
static int                    g_buf_count = 0;
static uint32_t               g_width = 0;
static uint32_t               g_height = 0;

/* Decoded frame output */

static uint16_t              *g_rgbbuf = NULL;       /* RGB565 output buffer */
static struct camera_frame    g_frame;               /* Returned frame info */

/* Private snapshot of one captured JPEG frame */

static uint8_t               *g_framecopy = NULL;
static uint32_t               g_framecopy_size = 0;

/****************************************************************************
 * TJpgDec Callbacks
 ****************************************************************************/

static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
{
  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
  size_t avail = io->len - io->pos;

  if (nbyte > avail)
    {
      nbyte = avail;
    }

  if (buff)
    {
      memcpy(buff, io->data + io->pos, nbyte);
    }

  io->pos += nbyte;
  return nbyte;
}

static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
{
  uint8_t *src = (uint8_t *)bitmap;
  uint32_t x;
  uint32_t y;
  uint32_t cpw = jd->width < g_width ? jd->width : g_width;
  uint32_t cph = jd->height < g_height ? jd->height : g_height;

  for (y = rect->top; y <= rect->bottom && y < cph; y++)
    {
      for (x = rect->left; x <= rect->right && x < cpw; x++)
        {
          uint8_t b = *src++;
          uint8_t g = *src++;
          uint8_t r = *src++;
          g_rgbbuf[y * cpw + x] =
            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
        }

      if (rect->right >= cpw)
        {
          src += (rect->right - cpw + 1) * 3;
        }
    }

  return 1;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int camera_open(const char *dev_path, uint32_t width, uint32_t height)
{
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  int ret;
  int i;

  g_width = width;
  g_height = height;

  /* Allocate RGB output buffer */

  g_rgbbuf = (uint16_t *)malloc(width * height * sizeof(uint16_t));
  if (!g_rgbbuf)
    {
      syslog(LOG_ERR, "CAM: failed to alloc rgbbuf\n");
      return -ENOMEM;
    }

  /* Allocate frame copy buffer (max JPEG size) */

  g_framecopy_size = width * height * 2;
  g_framecopy = (uint8_t *)malloc(g_framecopy_size);
  if (!g_framecopy)
    {
      syslog(LOG_ERR, "CAM: failed to alloc framecopy\n");
      free(g_rgbbuf);
      g_rgbbuf = NULL;
      return -ENOMEM;
    }

  /* Initialize video driver (creates /dev/video device node) */

  ret = capture_initialize(dev_path);
  if (ret != 0)
    {
      syslog(LOG_ERR, "CAM: capture_initialize failed: %d\n", ret);
      goto err_free;
    }

  /* Open V4L2 device */

  g_cap_fd = open(dev_path, O_RDWR);
  if (g_cap_fd < 0)
    {
      syslog(LOG_ERR, "CAM: open %s failed: %d\n", dev_path, errno);
      ret = -errno;
      goto err_uninit;
    }

  /* Set MJPEG format */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = width;
  fmt.fmt.pix.height = height;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.field = V4L2_FIELD_NONE;

  ret = ioctl(g_cap_fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
  if (ret < 0)
    {
      syslog(LOG_ERR, "CAM: VIDIOC_S_FMT failed: %d\n", errno);
      ret = -errno;
      goto err_close;
    }

  if (fmt.fmt.pix.sizeimage == 0)
    {
      fmt.fmt.pix.sizeimage = width * height * 2;
    }

  /* Request user-pointer buffers */

  memset(&req, 0, sizeof(req));
  req.count = CAPTURE_BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(g_cap_fd, VIDIOC_REQBUFS, (uintptr_t)&req);
  if (ret < 0)
    {
      syslog(LOG_ERR, "CAM: VIDIOC_REQBUFS failed: %d\n", errno);
      ret = -errno;
      goto err_close;
    }

  g_buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
  if (!g_buffers)
    {
      syslog(LOG_ERR, "CAM: failed to alloc buffer array\n");
      ret = -ENOMEM;
      goto err_close;
    }

  g_buf_count = req.count;

  for (i = 0; i < g_buf_count; i++)
    {
      g_buffers[i].length = fmt.fmt.pix.sizeimage;
      g_buffers[i].start = (uint8_t *)memalign(64, g_buffers[i].length);
      if (!g_buffers[i].start)
        {
          syslog(LOG_ERR, "CAM: failed to alloc buf %d\n", i);
          ret = -ENOMEM;
          goto err_free_buffers;
        }

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_USERPTR;
      buf.index = i;
      buf.m.userptr = (uintptr_t)g_buffers[i].start;
      buf.length = g_buffers[i].length;

      ret = ioctl(g_cap_fd, VIDIOC_QBUF, (uintptr_t)&buf);
      if (ret < 0)
        {
          syslog(LOG_ERR, "CAM: VIDIOC_QBUF[%d] failed: %d\n", i, errno);
          ret = -errno;
          goto err_free_buffers;
        }
    }

  /* Start streaming */

  ret = ioctl(g_cap_fd, VIDIOC_STREAMON, (uintptr_t)&type);
  if (ret < 0)
    {
      syslog(LOG_ERR, "CAM: VIDIOC_STREAMON failed: %d\n", errno);
      ret = -errno;
      goto err_free_buffers;
    }

  /* Setup frame info */

  g_frame.rgb565 = g_rgbbuf;
  g_frame.width = width;
  g_frame.height = height;

  syslog(LOG_INFO, "CAM: opened %s %ux%u MJPEG, %d buffers\n",
         dev_path, width, height, g_buf_count);
  return 0;

err_free_buffers:
  for (i = 0; i < g_buf_count; i++)
    {
      if (g_buffers[i].start)
        {
          free(g_buffers[i].start);
        }
    }

  free(g_buffers);
  g_buffers = NULL;
  g_buf_count = 0;

err_close:
  close(g_cap_fd);
  g_cap_fd = -1;

err_uninit:
  capture_uninitialize(dev_path);

err_free:
  free(g_rgbbuf);
  g_rgbbuf = NULL;
  free(g_framecopy);
  g_framecopy = NULL;
  return ret;
}

struct camera_frame *camera_capture(int timeout_ms)
{
  struct v4l2_buffer buf;
  int ret;

  if (g_cap_fd < 0)
    {
      return NULL;
    }

  /* Dequeue a filled buffer */

  memset(&buf, 0, sizeof(buf));
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  buf.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(g_cap_fd, VIDIOC_DQBUF, (uintptr_t)&buf);
  if (ret < 0)
    {
      syslog(LOG_ERR, "CAM: DQBUF failed: %d\n", errno);
      return NULL;
    }

  /* Snapshot frame into private buffer, then requeue immediately */

  uint32_t n = buf.bytesused;
  if (n > g_framecopy_size)
    {
      n = g_framecopy_size;
    }

  memcpy(g_framecopy, (const void *)buf.m.userptr, n);

  ret = ioctl(g_cap_fd, VIDIOC_QBUF, (uintptr_t)&buf);
  if (ret < 0)
    {
      syslog(LOG_ERR, "CAM: QBUF failed: %d\n", errno);
      return NULL;
    }

  /* Decode MJPEG to RGB565 */

  if (n > 1024)
    {
      static uint8_t jdwork[4096];
      JDEC jdec;
      JRESULT res;
      struct mjpeg_iodev_s iodev;

      iodev.data = g_framecopy;
      iodev.len = n;
      iodev.pos = 0;

      res = jd_prepare(&jdec, mjpeg_input, jdwork, sizeof(jdwork), &iodev);
      if (res == JDR_OK)
        {
          iodev.pos = 0; /* Reset for decompression pass */
          jd_decomp(&jdec, mjpeg_output, 0);

          g_frame.width = jdec.width < g_width ? jdec.width : g_width;
          g_frame.height = jdec.height < g_height ? jdec.height : g_height;
          return &g_frame;
        }
      else
        {
          syslog(LOG_WARNING, "CAM: JPEG decode failed: %d\n", res);
        }
    }

  return NULL;
}

void camera_close(void)
{
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  int i;

  if (g_cap_fd >= 0)
    {
      ioctl(g_cap_fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
      capture_uninitialize("/dev/video");
      close(g_cap_fd);
      g_cap_fd = -1;
    }

  if (g_buffers)
    {
      for (i = 0; i < g_buf_count; i++)
        {
          if (g_buffers[i].start)
            {
              free(g_buffers[i].start);
            }
        }

      free(g_buffers);
      g_buffers = NULL;
      g_buf_count = 0;
    }

  if (g_rgbbuf)
    {
      free(g_rgbbuf);
      g_rgbbuf = NULL;
    }

  if (g_framecopy)
    {
      free(g_framecopy);
      g_framecopy = NULL;
    }

  syslog(LOG_INFO, "CAM: closed\n");
}

