/****************************************************************************
 * apps/examples/human_detect/tflite_runner.cpp
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * TFLite Micro inference runner for SSD MobileNet person detection.
 * Handles model loading, preprocessing, inference, and post-processing.
 *
 * Expected model: SSD MobileNet v1/v2 quantized (UINT8 input, float output)
 * with TFLite_Detection_PostProcess custom op stripped.
 *
 * Raw SSD output tensors (without Detection_PostProcess):
 *   - boxes:   [1, N, 4]  float  (ymin, xmin, ymax, xmax) normalized
 *   - classes: [1, N]      float  (class ID)
 *   - scores:  [1, N]      float  (confidence)
 *   - num:     [1]         float  (number of valid detections)
 *
 * If the model HAS Detection_PostProcess fused, the outputs are:
 *   - [0]: [1, N, 4] float boxes
 *   - [1]: [1, N]    float classes
 *   - [2]: [1, N]    float scores
 *   - [3]: [1]       float num_detections
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <fstream>
#include <memory>
#include <algorithm>

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/system_setup.h"
#include "tensorflow/lite/schema/schema_generated.h"

#include "tflite_runner.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* SSD MobileNet typically has ~1917 or 1083 anchor boxes */

#define SSD_MAX_DETECTIONS  1917

/* NMS parameters */

#define NMS_IOU_THRESHOLD   0.6f

/****************************************************************************
 * Private Data
 ****************************************************************************/

static uint8_t *g_model_data = nullptr;
static uint8_t *g_arena = nullptr;
static int      g_arena_size = 0;

static tflite::MicroInterpreter *g_interpreter = nullptr;
static const tflite::Model     *g_model = nullptr;

/* Preprocessing buffer: 300x300x3 RGB UINT8 */

static uint8_t g_preprocess_buf[MODEL_INPUT_W * MODEL_INPUT_H * MODEL_INPUT_C];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: compute_iou
 *
 * Description:
 *   Compute Intersection over Union between two boxes.
 *
 ****************************************************************************/

static float compute_iou(const struct detection_box *a,
                         const struct detection_box *b)
{
  float x1 = std::max(a->xmin, b->xmin);
  float y1 = std::max(a->ymin, b->ymin);
  float x2 = std::min(a->xmax, b->xmax);
  float y2 = std::min(a->ymax, b->ymax);

  float inter = std::max(0.0f, x2 - x1) * std::max(0.0f, y2 - y1);
  float area_a = (a->xmax - a->xmin) * (a->ymax - a->ymin);
  float area_b = (b->xmax - b->xmin) * (b->ymax - b->ymin);
  float union_area = area_a + area_b - inter;

  return union_area > 0 ? inter / union_area : 0;
}

/****************************************************************************
 * Name: nms_filter
 *
 * Description:
 *   Apply Non-Maximum Suppression to filter overlapping detections.
 *   Keeps the highest-scoring box when IoU > threshold.
 *
 ****************************************************************************/

static int nms_filter(struct detection_box *boxes, int count,
                      float iou_threshold)
{
  /* Sort by score descending */

  for (int i = 0; i < count - 1; i++)
    {
      for (int j = i + 1; j < count; j++)
        {
          if (boxes[j].score > boxes[i].score)
            {
              struct detection_box tmp = boxes[i];
              boxes[i] = boxes[j];
              boxes[j] = tmp;
            }
        }
    }

  /* Suppress overlapping boxes */

  int kept = 0;
  bool suppressed[DETECT_MAX_BOXES];
  memset(suppressed, 0, sizeof(suppressed));

  for (int i = 0; i < count && kept < DETECT_MAX_BOXES; i++)
    {
      if (suppressed[i])
        {
          continue;
        }

      boxes[kept++] = boxes[i];

      for (int j = i + 1; j < count; j++)
        {
          if (!suppressed[j] &&
              boxes[j].class_id == boxes[i].class_id &&
              compute_iou(&boxes[i], &boxes[j]) > iou_threshold)
            {
              suppressed[j] = true;
            }
        }
    }

  return kept;
}

/****************************************************************************
 * Name: preprocess_frame
 *
 * Description:
 *   Convert RGB565 frame to 300x300 RGB UINT8 using nearest-neighbor
 *   scaling.  Output is written to g_preprocess_buf.
 *
 ****************************************************************************/

static void preprocess_frame(const uint16_t *rgb565, int src_w, int src_h)
{
  for (int y = 0; y < MODEL_INPUT_H; y++)
    {
      int sy = y * src_h / MODEL_INPUT_H;
      if (sy >= src_h)
        {
          sy = src_h - 1;
        }

      for (int x = 0; x < MODEL_INPUT_W; x++)
        {
          int sx = x * src_w / MODEL_INPUT_W;
          if (sx >= src_w)
            {
              sx = src_w - 1;
            }

          uint16_t pixel = rgb565[sy * src_w + sx];

          /* RGB565 → RGB888 */

          uint8_t r = ((pixel >> 11) & 0x1f) * 255 / 31;
          uint8_t g = ((pixel >> 5) & 0x3f) * 255 / 63;
          uint8_t b = (pixel & 0x1f) * 255 / 31;

          int idx = (y * MODEL_INPUT_W + x) * 3;
          g_preprocess_buf[idx + 0] = r;
          g_preprocess_buf[idx + 1] = g;
          g_preprocess_buf[idx + 2] = b;
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int tflite_init(const char *model_path, int arena_size)
{
  /* Load model from filesystem */

  std::ifstream ifs(model_path, std::ios::binary | std::ios::ate);
  if (!ifs.is_open())
    {
      printf("TFLITE: failed to open model: %s\n", model_path);
      return -1;
    }

  size_t model_size = ifs.tellg();
  ifs.seekg(0, std::ios::beg);

  g_model_data = new (std::nothrow) uint8_t[model_size];
  if (!g_model_data)
    {
      printf("TFLITE: failed to alloc model buf (%zu bytes)\n", model_size);
      return -1;
    }

  ifs.read(reinterpret_cast<char *>(g_model_data), model_size);
  ifs.close();

  printf("TFLITE: loaded model %s (%zu bytes)\n", model_path, model_size);

  /* Parse model */

  g_model = tflite::GetModel(g_model_data);
  if (g_model->version() != TFLITE_SCHEMA_VERSION)
    {
      printf("TFLITE: model schema mismatch: %lu vs %d\n",
             (unsigned long)g_model->version(), TFLITE_SCHEMA_VERSION);
      goto err_free_model;
    }

  /* Register ops needed by SSD MobileNet.
   * Register all commonly needed ops to handle various model variants.
   */

  {
    static tflite::MicroMutableOpResolver<16> resolver;
    resolver.AddConv2D();
    resolver.AddDepthwiseConv2D();
    resolver.AddMaxPool2D();
    resolver.AddAveragePool2D();
    resolver.AddReshape();
    resolver.AddSoftmax();
    resolver.AddConcatenation();
    resolver.AddAdd();
    resolver.AddMul();
    resolver.AddQuantize();
    resolver.AddDequantize();
    resolver.AddLogistic();
    resolver.AddCustom("TFLite_Detection_PostProcess",
                        nullptr);

    /* Allocate arena */

    g_arena_size = arena_size;
    g_arena = new (std::nothrow) uint8_t[g_arena_size];
    if (!g_arena)
      {
        printf("TFLITE: failed to alloc arena (%d bytes)\n", arena_size);
        goto err_free_model;
      }

    printf("TFLITE: arena allocated %d bytes\n", g_arena_size);

    /* Create interpreter */

    static tflite::MicroInterpreter static_interpreter(
        g_model, resolver, g_arena, g_arena_size);
    g_interpreter = &static_interpreter;

    /* Allocate tensors */

    TfLiteStatus status = g_interpreter->AllocateTensors();
    if (status != kTfLiteOk)
      {
        printf("TFLITE: AllocateTensors failed\n");
        goto err_free_arena;
      }

    printf("TFLITE: interpreter ready, input tensor type=%d size=%zu\n",
           g_interpreter->input(0)->type,
           g_interpreter->input(0)->bytes);
  }

  return 0;

err_free_arena:
  delete[] g_arena;
  g_arena = nullptr;

err_free_model:
  delete[] g_model_data;
  g_model_data = nullptr;
  return -1;
}

int tflite_detect(const uint16_t *rgb565_buf, int src_width, int src_height,
                  struct detect_result *result)
{
  if (!g_interpreter || !result)
    {
      return -1;
    }

  memset(result, 0, sizeof(*result));

  /* Preprocess: RGB565 → 300x300 RGB UINT8 */

  preprocess_frame(rgb565_buf, src_width, src_height);

  /* Copy preprocessed data to input tensor */

  TfLiteTensor *input = g_interpreter->input(0);
  if (input->type == kTfLiteUInt8)
    {
      memcpy(input->data.uint8, g_preprocess_buf,
             MODEL_INPUT_W * MODEL_INPUT_H * MODEL_INPUT_C);
    }
  else if (input->type == kTfLiteFloat32)
    {
      /* Some models expect float input; convert UINT8 → float */

      float *dst = input->data.f;
      for (int i = 0; i < MODEL_INPUT_W * MODEL_INPUT_H * MODEL_INPUT_C; i++)
        {
          dst[i] = g_preprocess_buf[i] / 255.0f;
        }
    }
  else
    {
      printf("TFLITE: unsupported input type %d\n", input->type);
      return -1;
    }

  /* Run inference */

  TfLiteStatus status = g_interpreter->Invoke();
  if (status != kTfLiteOk)
    {
      printf("TFLITE: Invoke failed\n");
      return -1;
    }

  /* Parse output tensors.
   *
   * SSD MobileNet with Detection_PostProcess fused has 4 outputs:
   *   output[0]: [1, N, 4] boxes (ymin, xmin, ymax, xmax)
   *   output[1]: [1, N]    classes
   *   output[2]: [1, N]    scores
   *   output[3]: [1]       num_detections
   *
   * Without the custom op (raw SSD), outputs are similar but may be
   * quantized. We handle both float and UINT8 output tensors.
   */

  int num_outputs = g_interpreter->outputs_size();
  if (num_outputs < 3)
    {
      printf("TFLITE: unexpected output count: %d\n", num_outputs);
      return -1;
    }

  const TfLiteTensor *out_boxes = g_interpreter->output(0);
  const TfLiteTensor *out_classes = g_interpreter->output(1);
  const TfLiteTensor *out_scores = g_interpreter->output(2);
  const TfLiteTensor *out_num = nullptr;

  int num_detections = SSD_MAX_DETECTIONS;
  if (num_outputs >= 4)
    {
      out_num = g_interpreter->output(3);
      if (out_num->type == kTfLiteFloat32)
        {
          num_detections = (int)out_num->data.f[0];
        }
      else if (out_num->type == kTfLiteUInt8)
        {
          float scale = out_num->params.scale;
          int zp = out_num->params.zero_point;
          num_detections = (int)(out_num->data.uint8[0] - zp) * scale;
        }
    }

  if (num_detections > SSD_MAX_DETECTIONS)
    {
      num_detections = SSD_MAX_DETECTIONS;
    }

  /* Collect person detections above threshold */

  struct detection_box person_boxes[DETECT_MAX_BOXES];
  int person_count = 0;

  for (int i = 0; i < num_detections && person_count < DETECT_MAX_BOXES; i++)
    {
      float score;
      int class_id;

      /* Read score */

      if (out_scores->type == kTfLiteFloat32)
        {
          score = out_scores->data.f[i];
        }
      else
        {
          float scale = out_scores->params.scale;
          int zp = out_scores->params.zero_point;
          score = (out_scores->data.uint8[i] - zp) * scale;
        }

      if (score < DETECT_THRESHOLD)
        {
          continue;
        }

      /* Read class ID */

      if (out_classes->type == kTfLiteFloat32)
        {
          class_id = (int)out_classes->data.f[i];
        }
      else
        {
          float scale = out_classes->params.scale;
          int zp = out_classes->params.zero_point;
          class_id = (int)((out_classes->data.uint8[i] - zp) * scale);
        }

      /* Filter for person class (COCO ID 0) */

      if (class_id != DETECT_PERSON_CLASS)
        {
          continue;
        }

      /* Read box coordinates (ymin, xmin, ymax, xmax) */

      float ymin, xmin, ymax, xmax;
      if (out_boxes->type == kTfLiteFloat32)
        {
          const float *box = &out_boxes->data.f[i * 4];
          ymin = box[0];
          xmin = box[1];
          ymax = box[2];
          xmax = box[3];
        }
      else
        {
          float scale = out_boxes->params.scale;
          int zp = out_boxes->params.zero_point;
          const uint8_t *box = &out_boxes->data.uint8[i * 4];
          ymin = (box[0] - zp) * scale;
          xmin = (box[1] - zp) * scale;
          ymax = (box[2] - zp) * scale;
          xmax = (box[3] - zp) * scale;
        }

      /* Clamp to [0, 1] */

      ymin = std::max(0.0f, std::min(1.0f, ymin));
      xmin = std::max(0.0f, std::min(1.0f, xmin));
      ymax = std::max(0.0f, std::min(1.0f, ymax));
      xmax = std::max(0.0f, std::min(1.0f, xmax));

      person_boxes[person_count].ymin = ymin;
      person_boxes[person_count].xmin = xmin;
      person_boxes[person_count].ymax = ymax;
      person_boxes[person_count].xmax = xmax;
      person_boxes[person_count].score = score;
      person_boxes[person_count].class_id = class_id;
      person_count++;
    }

  /* Apply NMS */

  result->num_detections = nms_filter(person_boxes, person_count,
                                       NMS_IOU_THRESHOLD);
  for (int i = 0; i < result->num_detections; i++)
    {
      result->boxes[i] = person_boxes[i];
    }

  return 0;
}

void tflite_deinit(void)
{
  g_interpreter = nullptr;
  g_model = nullptr;

  if (g_arena)
    {
      delete[] g_arena;
      g_arena = nullptr;
    }

  if (g_model_data)
    {
      delete[] g_model_data;
      g_model_data = nullptr;
    }

  printf("TFLITE: deinitialized\n");
}

