#define CAPTURE_WIDTH    320
#define CAPTURE_HEIGHT   240
#define FB_DEV_PATH      "/dev/lcd0"

/* Colors in RGB565 */

#define COLOR_GREEN      0x07E0
#define COLOR_RED        0xF800
#define COLOR_WHITE      0xFFFF
#define COLOR_BLACK      0x0000
#define COLOR_YELLOW     0xFFE0

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int g_fbfd = -1;
static struct fb_videoinfo_s g_vinfo;
static volatile bool g_running = true;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void signal_handler(int sig)
{
  (void)sig;
  g_running = false;
}

static int fb_open(void)
{
  int ret;

  g_fbfd = open(FB_DEV_PATH, O_RDWR);
  if (g_fbfd < 0)
    {
      printf("ERROR: open %s failed\n", FB_DEV_PATH);
      return -1;
    }

  ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
  if (ret < 0)
    {
      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed\n");
      close(g_fbfd);
      g_fbfd = -1;
      return -1;
    }

  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
  return 0;
}

static void fb_blit(uint16_t *buf, uint32_t w, uint32_t h)
{
  struct lcddev_area_s area;

  memset(&area, 0, sizeof(area));
  area.row_start = 0;
  area.row_end   = h - 1;
  area.col_start = 0;
  area.col_end   = w - 1;
  area.stride    = w * 2;
  area.data      = (FAR uint8_t *)buf;

  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
}

static void draw_detection_overlay(uint16_t *buf, int w, int h,
                                   const struct detect_result *result)
{
  for (int i = 0; i < result->num_detections; i++)
    {
      const struct detection_box *box = &result->boxes[i];

      /* Convert normalized coordinates to pixel coordinates */

      int x1 = (int)(box->xmin * w);
      int y1 = (int)(box->ymin * h);
      int x2 = (int)(box->xmax * w);
      int y2 = (int)(box->ymax * h);

      /* Clamp to frame bounds */

      if (x1 < 0) x1 = 0;
      if (y1 < 0) y1 = 0;
      if (x2 >= w) x2 = w - 1;
      if (y2 >= h) y2 = h - 1;

      /* Draw green border (3 pixels wide) */

      for (int t = 0; t < 3; t++)
        {
          for (int x = x1; x <= x2; x++)
            {
              if (y1 + t < h)
                {
                  buf[(y1 + t) * w + x] = COLOR_GREEN;
                }

              if (y2 - t >= 0)
                {
                  buf[(y2 - t) * w + x] = COLOR_GREEN;
                }
            }

          for (int y = y1; y <= y2; y++)
            {
              if (x1 + t < w)
                {
                  buf[y * w + (x1 + t)] = COLOR_GREEN;
                }

              if (x2 - t >= 0)
                {
                  buf[y * w + (x2 - t)] = COLOR_GREEN;
                }
            }
        }

      /* Draw label above the box */

      char label[32];
      format_score_label(label, sizeof(label), box->score);

      int label_y = y1 - 12;
      if (label_y < 0)
        {
          label_y = 0;
        }

      font_draw_string_bg(buf, w, h, x1, label_y, label,
                          COLOR_WHITE, COLOR_BLACK);
    }
}

static void draw_status_bar(uint16_t *buf, int w, int h,
                            float fps, int num_detections)
{
  char status[64];

  if (num_detections > 0)
    {
      snprintf(status, sizeof(status), "%.1fFPS %d person(s)",
               fps, num_detections);
    }
  else
    {
      snprintf(status, sizeof(status), "%.1fFPS No person", fps);
    }

  /* Draw at bottom-left of frame */

  font_draw_string_bg(buf, w, h, 2, h - 12, status,
                      COLOR_YELLOW, COLOR_BLACK);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

extern "C" int main(int argc, char *argv[])
{
  const char *model_path = CONFIG_EXAMPLES_HUMAN_DETECT_MODEL_PATH;
  int arena_size = CONFIG_EXAMPLES_HUMAN_DETECT_ARENA_SIZE;

  struct camera_frame *frame;
  struct detect_result result;

  /* Timing */

  struct timeval tv_start;
  struct timeval tv_now;
  int frame_count = 0;
  float fps = 0.0f;
  gettimeofday(&tv_start, NULL);

  printf("=== Human Detection Application ===\n");

  /* Setup signal handler for graceful exit */

  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  /* Initialize LCD */

  if (fb_open() < 0)
    {
      printf("ERROR: LCD init failed\n");
      return 1;
    }

  /* Initialize TFLite Micro */

  printf("Loading model: %s\n", model_path);
  if (tflite_init(model_path, arena_size) < 0)
    {
      printf("ERROR: TFLite init failed\n");
      close(g_fbfd);
      return 1;
    }

  /* Initialize camera */

  if (camera_open("/dev/video", CAPTURE_WIDTH, CAPTURE_HEIGHT) < 0)
    {
      printf("ERROR: Camera open failed\n");
      tflite_deinit();
      close(g_fbfd);
      return 1;
    }

  printf("Human detection started (Ctrl-C to stop)\n");

  /* Main loop */

  while (g_running)
    {
      /* Capture and decode one frame */

      frame = camera_capture(-1);
      if (!frame)
        {
          continue;
        }

      /* Run person detection */

      gettimeofday(&tv_now, NULL);
      long t0 = tv_now.tv_sec * 1000000 + tv_now.tv_usec;

      tflite_detect(frame->rgb565, frame->width, frame->height, &result);

      gettimeofday(&tv_now, NULL);
      long t1 = tv_now.tv_sec * 1000000 + tv_now.tv_usec;
      long infer_us = t1 - t0;

      /* Draw detection overlay on the frame */

      draw_detection_overlay(frame->rgb565, frame->width, frame->height,
                             &result);

      /* Update FPS counter */

      frame_count++;
      gettimeofday(&tv_now, NULL);
      long elapsed_us = (tv_now.tv_sec - tv_start.tv_sec) * 1000000 +
                        (tv_now.tv_usec - tv_start.tv_usec);

      if (elapsed_us > 1000000) /* Update FPS every second */
        {
          fps = frame_count * 1000000.0f / elapsed_us;
          frame_count = 0;
          tv_start = tv_now;

          syslog(LOG_INFO,
                 "HUMAN: %.1f FPS, infer=%ldms, detections=%d\n",
                 fps, infer_us / 1000, result.num_detections);
        }

      /* Draw status bar */

      draw_status_bar(frame->rgb565, frame->width, frame->height,
                      fps, result.num_detections);

      /* Blit frame to LCD */

      fb_blit(frame->rgb565, frame->width, frame->height);
    }

  printf("\nStopping...\n");

  /* Cleanup */

  camera_close();
  tflite_deinit();

  if (g_fbfd >= 0)
    {
      close(g_fbfd);
      g_fbfd = -1;
    }

  printf("Human detection stopped.\n");
  return 0;
}

