76	
77	/****************************************************************************
78	 * Name: compute_iou
79	 *
80	 * Description:
81	 *   Compute Intersection over Union between two boxes.
82	 *
83	 ****************************************************************************/
84	
85	static float compute_iou(const struct detection_box *a,
86	                         const struct detection_box *b)
87	{
88	  float x1 = std::max(a->xmin, b->xmin);
89	  float y1 = std::max(a->ymin, b->ymin);
90	  float x2 = std::min(a->xmax, b->xmax);
91	  float y2 = std::min(a->ymax, b->ymax);
92	
93	  float inter = std::max(0.0f, x2 - x1) * std::max(0.0f, y2 - y1);
94	  float area_a = (a->xmax - a->xmin) * (a->ymax - a->ymin);
95	  float area_b = (b->xmax - b->xmin) * (b->ymax - b->ymin);
96	  float union_area = area_a + area_b - inter;
97	
98	  return union_area > 0 ? inter / union_area : 0;
99	}
100	
101	/****************************************************************************
102	 * Name: nms_filter
103	 *
104	 * Description:
105	 *   Apply Non-Maximum Suppression to filter overlapping detections.
106	 *   Keeps the highest-scoring box when IoU > threshold.
107	 *
108	 ****************************************************************************/
109	
110	static int nms_filter(struct detection_box *boxes, int count,
111	                      float iou_threshold)
112	{
113	  /* Sort by score descending */
114	
115	  for (int i = 0; i < count - 1; i++)
116	    {
117	      for (int j = i + 1; j < count; j++)
118	        {
119	          if (boxes[j].score > boxes[i].score)
120	            {
121	              struct detection_box tmp = boxes[i];
122	              boxes[i] = boxes[j];
123	              boxes[j] = tmp;
124	            }
125	        }
126	    }
127	
128	  /* Suppress overlapping boxes */
129	
130	  int kept = 0;
131	  bool suppressed[DETECT_MAX_BOXES];
132	  memset(suppressed, 0, sizeof(suppressed));
133	
134	  for (int i = 0; i < count && kept < DETECT_MAX_BOXES; i++)
135	    {
136	      if (suppressed[i])
137	        {
138	          continue;
139	        }
140	
141	      boxes[kept++] = boxes[i];
142	
143	      for (int j = i + 1; j < count; j++)
144	        {
145	          if (!suppressed[j] &&
146	              boxes[j].class_id == boxes[i].class_id &&
147	              compute_iou(&boxes[i], &boxes[j]) > iou_threshold)
148	            {
149	              suppressed[j] = true;
150	            }
151	        }
152	    }
153	
154	  return kept;
155	}
