157	/****************************************************************************
158	 * Name: preprocess_frame
159	 *
160	 * Description:
161	 *   Convert RGB565 frame to 300x300 RGB UINT8 using nearest-neighbor
162	 *   scaling.  Output is written to g_preprocess_buf.
163	 *
164	 ****************************************************************************/
165	
166	static void preprocess_frame(const uint16_t *rgb565, int src_w, int src_h)
167	{
168	  for (int y = 0; y < MODEL_INPUT_H; y++)
169	    {
170	      int sy = y * src_h / MODEL_INPUT_H;
171	      if (sy >= src_h)
172	        {
173	          sy = src_h - 1;
174	        }
175	
176	      for (int x = 0; x < MODEL_INPUT_W; x++)
177	        {
178	          int sx = x * src_w / MODEL_INPUT_W;
179	          if (sx >= src_w)
180	            {
181	              sx = src_w - 1;
182	            }
183	
184	          uint16_t pixel = rgb565[sy * src_w + sx];
185	
186	          /* RGB565 → RGB888 */
187	
188	          uint8_t r = ((pixel >> 11) & 0x1f) * 255 / 31;
189	          uint8_t g = ((pixel >> 5) & 0x3f) * 255 / 63;
190	          uint8_t b = (pixel & 0x1f) * 255 / 31;
191	
192	          int idx = (y * MODEL_INPUT_W + x) * 3;
193	          g_preprocess_buf[idx + 0] = r;
194	          g_preprocess_buf[idx + 1] = g;
195	          g_preprocess_buf[idx + 2] = b;
196	        }
197	    }
198	}
