229	
230	  /* Parse model */
231	
232	  g_model = tflite::GetModel(g_model_data);
233	  if (g_model->version() != TFLITE_SCHEMA_VERSION)
234	    {
235	      printf("TFLITE: model schema mismatch: %lu vs %d\n",
236	             (unsigned long)g_model->version(), TFLITE_SCHEMA_VERSION);
237	      goto err_free_model;
238	    }
239	
240	  /* Register ops needed by SSD MobileNet.
241	   * Register all commonly needed ops to handle various model variants.
242	   */
243	
244	  {
245	    static tflite::MicroMutableOpResolver<16> resolver;
246	    resolver.AddConv2D();
247	    resolver.AddDepthwiseConv2D();
248	    resolver.AddMaxPool2D();
249	    resolver.AddAveragePool2D();
250	    resolver.AddReshape();
251	    resolver.AddSoftmax();
252	    resolver.AddConcatenation();
253	    resolver.AddAdd();
254	    resolver.AddMul();
255	    resolver.AddQuantize();
256	    resolver.AddDequantize();
257	    resolver.AddLogistic();
258	    resolver.AddCustom("TFLite_Detection_PostProcess",
259	                        nullptr);
260	
261	    /* Allocate arena */
262	
263	    g_arena_size = arena_size;
264	    g_arena = new (std::nothrow) uint8_t[g_arena_size];
265	    if (!g_arena)
266	      {
267	        printf("TFLITE: failed to alloc arena (%d bytes)\n", arena_size);
268	        goto err_free_model;
269	      }
270	
271	    printf("TFLITE: arena allocated %d bytes\n", g_arena_size);
272	
273	    /* Create interpreter */
274	
275	    static tflite::MicroInterpreter static_interpreter(
276	        g_model, resolver, g_arena, g_arena_size);
277	    g_interpreter = &static_interpreter;
278	
279	    /* Allocate tensors */
280	
281	    TfLiteStatus status = g_interpreter->AllocateTensors();
282	    if (status != kTfLiteOk)
283	      {
284	        printf("TFLITE: AllocateTensors failed\n");
285	        goto err_free_arena;
286	      }
287	
288	    printf("TFLITE: interpreter ready, input tensor type=%d size=%zu\n",
289	           g_interpreter->input(0)->type,
290	           g_interpreter->input(0)->bytes);
291	  }
292	
293	  return 0;
294	
295	err_free_arena:
296	  delete[] g_arena;
297	  g_arena = nullptr;
298	
299	err_free_model:
300	  delete[] g_model_data;
301	  g_model_data = nullptr;
302	  return -1;
303	}
304	
305	int tflite_detect(const uint16_t *rgb565_buf, int src_width, int src_height,
306	                  struct detect_result *result)
307	{
308	  if (!g_interpreter || !result)
309	    {
310	      return -1;
311	    }
312	
313	  memset(result, 0, sizeof(*result));
314	
315	  /* Preprocess: RGB565 → 300x300 RGB UINT8 */
316	
317	  preprocess_frame(rgb565_buf, src_width, src_height);
318	
319	  /* Copy preprocessed data to input tensor */
320	
321	  TfLiteTensor *input = g_interpreter->input(0);
322	  if (input->type == kTfLiteUInt8)
323	    {
324	      memcpy(input->data.uint8, g_preprocess_buf,
325	             MODEL_INPUT_W * MODEL_INPUT_H * MODEL_INPUT_C);
326	    }
327	  else if (input->type == kTfLiteFloat32)
328	    {
329	      /* Some models expect float input; convert UINT8 → float */
330	
331	      float *dst = input->data.f;
332	      for (int i = 0; i < MODEL_INPUT_W * MODEL_INPUT_H * MODEL_INPUT_C; i++)
333	        {
334	          dst[i] = g_preprocess_buf[i] / 255.0f;
335	        }
336	    }
337	  else
338	    {
339	      printf("TFLITE: unsupported input type %d\n", input->type);
340	      return -1;
341	    }
342	
343	  /* Run inference */
344	
345	  TfLiteStatus status = g_interpreter->Invoke();
346	  if (status != kTfLiteOk)
347	    {
348	      printf("TFLITE: Invoke failed\n");
349	      return -1;
350	    }
351	
352	  /* Parse output tensors.
353	   *
354	   * SSD MobileNet with Detection_PostProcess fused has 4 outputs:
355	   *   output[0]: [1, N, 4] boxes (ymin, xmin, ymax, xmax)
356	   *   output[1]: [1, N]    classes
357	   *   output[2]: [1, N]    scores
358	   *   output[3]: [1]       num_detections
359	   *
360	   * Without the custom op (raw SSD), outputs are similar but may be
361	   * quantized. We handle both float and UINT8 output tensors.
362	   */
363	
364	  int num_outputs = g_interpreter->outputs_size();
365	  if (num_outputs < 3)
366	    {
367	      printf("TFLITE: unexpected output count: %d\n", num_outputs);
368	      return -1;
369	    }
370	
371	  const TfLiteTensor *out_boxes = g_interpreter->output(0);
372	  const TfLiteTensor *out_classes = g_interpreter->output(1);
373	  const TfLiteTensor *out_scores = g_interpreter->output(2);
374	  const TfLiteTensor *out_num = nullptr;
375	
376	  int num_detections = SSD_MAX_DETECTIONS;
377	  if (num_outputs >= 4)
378	    {
379	      out_num = g_interpreter->output(3);
380	      if (out_num->type == kTfLiteFloat32)
381	        {
382	          num_detections = (int)out_num->data.f[0];
383	        }
384	      else if (out_num->type == kTfLiteUInt8)
385	        {
386	          float scale = out_num->params.scale;
387	          int zp = out_num->params.zero_point;
388	          num_detections = (int)(out_num->data.uint8[0] - zp) * scale;
389	        }
390	    }
391	
392	  if (num_detections > SSD_MAX_DETECTIONS)
393	    {
394	      num_detections = SSD_MAX_DETECTIONS;
395	    }
396	
397	  /* Collect person detections above threshold */
398	
399	  struct detection_box person_boxes[DETECT_MAX_BOXES];
400	  int person_count = 0;
401	
402	  for (int i = 0; i < num_detections && person_count < DETECT_MAX_BOXES; i++)
403	    {
404	      float score;
405	      int class_id;
406	
407	      /* Read score */
408	
409	      if (out_scores->type == kTfLiteFloat32)
410	        {
411	          score = out_scores->data.f[i];
412	        }
413	      else
414	        {
415	          float scale = out_scores->params.scale;
416	          int zp = out_scores->params.zero_point;
417	          score = (out_scores->data.uint8[i] - zp) * scale;
418	        }
419	
420	      if (score < DETECT_THRESHOLD)
421	        {
422	          continue;
423	        }
424	
425	      /* Read class ID */
426	
427	      if (out_classes->type == kTfLiteFloat32)
428	        {
429	          class_id = (int)out_classes->data.f[i];
430	        }
431	      else
432	        {
433	          float scale = out_classes->params.scale;
434	          int zp = out_classes->params.zero_point;
435	          class_id = (int)((out_classes->data.uint8[i] - zp) * scale);
436	        }
437	
438	      /* Filter for person class (COCO ID 0) */
439	
440	      if (class_id != DETECT_PERSON_CLASS)
441	        {
442	          continue;
443	        }
444	
445	      /* Read box coordinates (ymin, xmin, ymax, xmax) */
446	
447	      float ymin, xmin, ymax, xmax;
448	      if (out_boxes->type == kTfLiteFloat32)
449	        {
450	          const float *box = &out_boxes->data.f[i * 4];
451	          ymin = box[0];
452	          xmin = box[1];
453	          ymax = box[2];
454	          xmax = box[3];
455	        }
456	      else
457	        {
458	          float scale = out_boxes->params.scale;
459	          int zp = out_boxes->params.zero_point;
460	          const uint8_t *box = &out_boxes->data.uint8[i * 4];
461	          ymin = (box[0] - zp) * scale;
462	          xmin = (box[1] - zp) * scale;
463	          ymax = (box[2] - zp) * scale;
464	          xmax = (box[3] - zp) * scale;
465	        }
466	
467	      /* Clamp to [0, 1] */
468	
469	      ymin = std::max(0.0f, std::min(1.0f, ymin));
470	      xmin = std::max(0.0f, std::min(1.0f, xmin));
471	      ymax = std::max(0.0f, std::min(1.0f, ymax));
472	      xmax = std::max(0.0f, std::min(1.0f, xmax));
473	
474	      person_boxes[person_count].ymin = ymin;
475	      person_boxes[person_count].xmin = xmin;
476	      person_boxes[person_count].ymax = ymax;
477	      person_boxes[person_count].xmax = xmax;
478	      person_boxes[person_count].score = score;
479	      person_boxes[person_count].class_id = class_id;
480	      person_count++;
481	    }
482	
483	  /* Apply NMS */
484	
485	  result->num_detections = nms_filter(person_boxes, person_count,
486	                                       NMS_IOU_THRESHOLD);
487	  for (int i = 0; i < result->num_detections; i++)
488	    {
489	      result->boxes[i] = person_boxes[i];
490	    }
491	
492	  return 0;
493	}
