/****************************************************************************
 * apps/examples/human_detect/tflite_runner.cpp
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * TFLite Micro inference runner for SSD MobileNet v2 quantized person
 * detection.  Uses the stripped model (no custom Detection_PostProcess op)
 * with raw SSD outputs decoded via pre-computed anchor boxes.
 *
 * Model: ssd_mobilenet_v2_quantized_stripped.tflite
 *   Input:  normalized_input_image_tensor [1, 300, 300, 3] UINT8
 *   Output[0]: raw_outputs/box_encodings   [1, 1917, 4]    UINT8
 *              quantized: scale=0.09133967, zero_point=179
 *   Output[1]: raw_outputs/class_predictions [1, 1917, 91]  UINT8
 *              quantized: scale=0.00390625, zero_point=0
 *
 * Box encoding uses Faster R-CNN box coder:
 *   y_center = (enc_y / y_scale) * anchor_h + anchor_cy
 *   x_center = (enc_x / x_scale) * anchor_w + anchor_cx
 *   half_h   = exp(enc_h / h_scale) * anchor_h / 2
 *   half_w   = exp(enc_w / w_scale) * anchor_w / 2
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <fstream>
#include <algorithm>

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/schema/schema_generated.h"

#include "tflite_runner.h"
#include "ssd_anchors.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SSD_NUM_CLASSES       91  /* COCO 90 classes + background */
#define SSD_BOX_CODER_YSCALE  10.0f
#define SSD_BOX_CODER_XSCALE  10.0f
#define SSD_BOX_CODER_HSCALE  5.0f
#define SSD_BOX_CODER_WSCALE  5.0f

/* Output quantization parameters (from model inspection) */

#define BOX_ENC_SCALE       0.09133967f
#define BOX_ENC_ZP          179
#define CLASS_PRED_SCALE    0.00390625f  /* 1/256 */
#define CLASS_PRED_ZP       0

/* NMS parameters (from pipeline.config) */

#define NMS_IOU_THRESHOLD   0.6f
#define NMS_MAX_DETECTIONS  10

/****************************************************************************
 * Private Data
 ****************************************************************************/

static uint8_t *g_model_data = nullptr;
static uint8_t *g_arena = nullptr;
static int      g_arena_size = 0;

static tflite::MicroInterpreter *g_interpreter = nullptr;
static const tflite::Model     *g_model = nullptr;

/* Preprocessing buffer: 300x300x3 RGB UINT8 */

static uint8_t g_preprocess_buf[MODEL_INPUT_W * MODEL_INPUT_H *
                                MODEL_INPUT_C];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline float fast_exp(float x)
{
  /* Approximate exp for small negative values (used in SSD box decoding).
   * Standard exp() works too but is slower on Cortex-A7 without FPU
   * optimization for transcendentals.
   */

  return expf(x);
}

static float compute_iou(const struct detection_box *a,
                         const struct detection_box *b)
{
  float x1 = std::max(a->xmin, b->xmin);
  float y1 = std::max(a->ymin, b->ymin);
  float x2 = std::min(a->xmax, b->xmax);
  float y2 = std::min(a->ymax, b->ymax);

  float inter = std::max(0.0f, x2 - x1) * std::max(0.0f, y2 - y1);
  float area_a = (a->xmax - a->xmin) * (a->ymax - a->ymin);
  float area_b = (b->xmax - b->xmin) * (b->ymax - b->ymin);
  float union_area = area_a + area_b - inter;

  return union_area > 0 ? inter / union_area : 0;
}

static int nms_filter(struct detection_box *boxes, int count,
                      float iou_threshold, int max_detections)
{
  /* Sort by score descending (simple selection sort) */

  for (int i = 0; i < count - 1; i++)
    {
      int best = i;
      for (int j = i + 1; j < count; j++)
        {
          if (boxes[j].score > boxes[best].score)
            {
              best = j;
            }
        }

      if (best != i)
        {
          struct detection_box tmp = boxes[i];
          boxes[i] = boxes[best];
          boxes[best] = tmp;
        }
    }

  /* Suppress overlapping boxes */

  int kept = 0;
  bool suppressed[DETECT_MAX_BOXES];
  memset(suppressed, 0, sizeof(suppressed));

  for (int i = 0; i < count && kept < max_detections; i++)
    {
      if (suppressed[i])
        {
          continue;
        }

      boxes[kept++] = boxes[i];

      for (int j = i + 1; j < count; j++)
        {
          if (!suppressed[j] &&
              compute_iou(&boxes[i], &boxes[j]) > iou_threshold)
            {
              suppressed[j] = true;
            }
        }
    }

  return kept;
}

/****************************************************************************
 * Name: ssd_decode_boxes
 *
 * Description:
 *   Decode raw SSD box encodings to actual coordinates using anchors
 *   and Faster R-CNN box coder parameters.
 *
 *   For each anchor i:
 *     anchor_cy = (anchors[i][0] + anchors[i][2]) / 2
 *     anchor_cx = (anchors[i][1] + anchors[i][3]) / 2
 *     anchor_h  = anchors[i][2] - anchors[i][0]
 *     anchor_w  = anchors[i][3] - anchors[i][1]
 *
 *     cy = (enc_y / y_scale) * anchor_h + anchor_cy
 *     cx = (enc_x / x_scale) * anchor_w + anchor_cx
 *     half_h = exp(enc_h / h_scale) * anchor_h / 2
 *     half_w = exp(enc_w / w_scale) * anchor_w / 2
 *
 *     ymin = cy - half_h
 *     xmin = cx - half_w
 *     ymax = cy + half_h
 *     xmax = cx + half_w
 *
 ****************************************************************************/

static void ssd_decode_boxes(const float *encodings,
                             float *decoded /* [N*4] */)
{
  for (int i = 0; i < SSD_NUM_ANCHORS; i++)
    {
      const float *enc = &encodings[i * 4];
      const float *anchor = g_ssd_anchors[i];

      /* Anchor center and size (anchors are in [ymin, xmin, ymax, xmax]) */

      float anchor_cy = (anchor[0] + anchor[2]) * 0.5f;
      float anchor_cx = (anchor[1] + anchor[3]) * 0.5f;
      float anchor_h = anchor[2] - anchor[0];
      float anchor_w = anchor[3] - anchor[1];

      /* Decode center */

      float cy = (enc[0] / SSD_BOX_CODER_YSCALE) * anchor_h + anchor_cy;
      float cx = (enc[1] / SSD_BOX_CODER_XSCALE) * anchor_w + anchor_cx;

      /* Decode size */

      float half_h = fast_exp(enc[2] / SSD_BOX_CODER_HSCALE) * anchor_h * 0.5f;
      float half_w = fast_exp(enc[3] / SSD_BOX_CODER_WSCALE) * anchor_w * 0.5f;

      /* Convert to corner format and clamp */

      float *out = &decoded[i * 4];
      out[0] = std::max(0.0f, std::min(1.0f, cy - half_h)); /* ymin */
      out[1] = std::max(0.0f, std::min(1.0f, cx - half_w)); /* xmin */
      out[2] = std::max(0.0f, std::min(1.0f, cy + half_h)); /* ymax */
      out[3] = std::max(0.0f, std::min(1.0f, cx + half_w)); /* xmax */
    }
}

/****************************************************************************
 * Name: preprocess_frame
 *
 * Description:
 *   Convert RGB565 frame to 300x300 RGB UINT8 using nearest-neighbor
 *   scaling.
 *
 ****************************************************************************/

static void preprocess_frame(const uint16_t *rgb565, int src_w, int src_h)
{
  for (int y = 0; y < MODEL_INPUT_H; y++)
    {
      int sy = y * src_h / MODEL_INPUT_H;
      if (sy >= src_h)
        {
          sy = src_h - 1;
        }

      for (int x = 0; x < MODEL_INPUT_W; x++)
        {
          int sx = x * src_w / MODEL_INPUT_W;
          if (sx >= src_w)
            {
              sx = src_w - 1;
            }

          uint16_t pixel = rgb565[sy * src_w + sx];

          /* RGB565 → RGB888 */

          uint8_t r = ((pixel >> 11) & 0x1f) * 255 / 31;
          uint8_t g = ((pixel >> 5) & 0x3f) * 255 / 63;
          uint8_t b = (pixel & 0x1f) * 255 / 31;

          int idx = (y * MODEL_INPUT_W + x) * 3;
          g_preprocess_buf[idx + 0] = r;
          g_preprocess_buf[idx + 1] = g;
          g_preprocess_buf[idx + 2] = b;
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int tflite_init(const char *model_path, int arena_size)
{
  /* Load model from filesystem */

  std::ifstream ifs(model_path, std::ios::binary | std::ios::ate);
  if (!ifs.is_open())
    {
      printf("TFLITE: failed to open model: %s\n", model_path);
      return -1;
    }

  size_t model_size = ifs.tellg();
  ifs.seekg(0, std::ios::beg);

  g_model_data = new (std::nothrow) uint8_t[model_size];
  if (!g_model_data)
    {
      printf("TFLITE: failed to alloc model buf (%zu bytes)\n", model_size);
      return -1;
    }

  ifs.read(reinterpret_cast<char *>(g_model_data), model_size);
  ifs.close();

  printf("TFLITE: loaded model %s (%zu bytes)\n", model_path, model_size);

  /* Parse model */

  g_model = tflite::GetModel(g_model_data);
  if (g_model->version() != TFLITE_SCHEMA_VERSION)
    {
      printf("TFLITE: model schema mismatch: %lu vs %d\n",
             (unsigned long)g_model->version(), TFLITE_SCHEMA_VERSION);
      goto err_free_model;
    }

  /* Register ops needed by stripped SSD MobileNet (no custom ops).
   * The model uses standard TFLite ops only.
   */

  {
    static tflite::MicroMutableOpResolver<14> resolver;
    resolver.AddConv2D();
    resolver.AddDepthwiseConv2D();
    resolver.AddMaxPool2D();
    resolver.AddAveragePool2D();
    resolver.AddReshape();
    resolver.AddSoftmax();
    resolver.AddConcatenation();
    resolver.AddAdd();
    resolver.AddMul();
    resolver.AddQuantize();
    resolver.AddDequantize();
    resolver.AddLogistic();
    resolver.AddHardSwish();

    /* Allocate arena */

    g_arena_size = arena_size;
    g_arena = new (std::nothrow) uint8_t[g_arena_size];
    if (!g_arena)
      {
        printf("TFLITE: failed to alloc arena (%d bytes)\n", arena_size);
        goto err_free_model;
      }

    printf("TFLITE: arena allocated %d bytes\n", g_arena_size);

    /* Create interpreter */

    static tflite::MicroInterpreter static_interpreter(
        g_model, resolver, g_arena, g_arena_size);
    g_interpreter = &static_interpreter;

    /* Allocate tensors */

    TfLiteStatus status = g_interpreter->AllocateTensors();
    if (status != kTfLiteOk)
      {
        printf("TFLITE: AllocateTensors failed\n");
        goto err_free_arena;
      }

    printf("TFLITE: interpreter ready, input type=%d size=%zu\n",
           g_interpreter->input(0)->type,
           g_interpreter->input(0)->bytes);
  }

  return 0;

err_free_arena:
  delete[] g_arena;
  g_arena = nullptr;

err_free_model:
  delete[] g_model_data;
  g_model_data = nullptr;
  return -1;
}

int tflite_detect(const uint16_t *rgb565_buf, int src_width, int src_height,
                  struct detect_result *result)
{
  if (!g_interpreter || !result)
    {
      return -1;
    }

  memset(result, 0, sizeof(*result));

  /* Preprocess: RGB565 → 300x300 RGB UINT8 */

  preprocess_frame(rgb565_buf, src_width, src_height);

  /* Copy preprocessed data to input tensor */

  TfLiteTensor *input = g_interpreter->input(0);
  if (input->type == kTfLiteUInt8)
    {
      memcpy(input->data.uint8, g_preprocess_buf,
             MODEL_INPUT_W * MODEL_INPUT_H * MODEL_INPUT_C);
    }
  else if (input->type == kTfLiteFloat32)
    {
      float *dst = input->data.f;
      for (int i = 0; i < MODEL_INPUT_W * MODEL_INPUT_H * MODEL_INPUT_C; i++)
        {
          dst[i] = g_preprocess_buf[i] / 255.0f;
        }
    }
  else
    {
      printf("TFLITE: unsupported input type %d\n", input->type);
      return -1;
    }

  /* Run inference */

  TfLiteStatus status = g_interpreter->Invoke();
  if (status != kTfLiteOk)
    {
      printf("TFLITE: Invoke failed\n");
      return -1;
    }

  /* Parse raw SSD outputs.
   *
   * Output[0]: box_encodings   [1, 1917, 4] UINT8
   *   dequantize: float_val = (uint8_val - 179) * 0.09133967
   *
   * Output[1]: class_predictions [1, 1917, 91] UINT8
   *   dequantize: float_val = (uint8_val - 0) * 0.00390625
   *   Apply sigmoid to get probabilities (score_converter: SIGMOID)
   *
   * SSD box decoding with anchors and Faster R-CNN box coder:
   *   y_scale=10, x_scale=10, h_scale=5, w_scale=5
   */

  const TfLiteTensor *out_boxes = g_interpreter->output(0);
  const TfLiteTensor *out_classes = g_interpreter->output(1);

  /* Dequantize box encodings to float.
   * Stack buffer for decoded boxes — 1917 * 4 * 4 bytes = ~30KB.
   */

  float box_enc[SSD_NUM_ANCHORS * 4];
  if (out_boxes->type == kTfLiteUInt8)
    {
      const uint8_t *src = out_boxes->data.uint8;
      for (int i = 0; i < SSD_NUM_ANCHORS * 4; i++)
        {
          box_enc[i] = (src[i] - BOX_ENC_ZP) * BOX_ENC_SCALE;
        }
    }
  else
    {
      memcpy(box_enc, out_boxes->data.f, sizeof(box_enc));
    }

  /* Decode boxes using anchors */

  float decoded_boxes[SSD_NUM_ANCHORS * 4];
  ssd_decode_boxes(box_enc, decoded_boxes);

  /* Find best class for each anchor and filter for person.
   * Class predictions: [1, 1917, 91] — apply sigmoid, find argmax.
   * Person class is COCO ID 0 (after background).
   * In the COCO label map used by TF Object Detection:
   *   class 0 = background, class 1 = person
   */

  struct detection_box person_boxes[SSD_NUM_ANCHORS];
  int person_count = 0;

  for (int i = 0; i < SSD_NUM_ANCHORS && person_count < DETECT_MAX_BOXES; i++)
    {
      /* Find best class score (sigmoid of dequantized logit) */

      float best_score = 0;
      int best_class = 0;

      for (int c = 0; c < SSD_NUM_CLASSES; c++)
        {
          float logit;
          if (out_classes->type == kTfLiteUInt8)
            {
              logit = (out_classes->data.uint8[i * SSD_NUM_CLASSES + c]
                       - CLASS_PRED_ZP) * CLASS_PRED_SCALE;
            }
          else
            {
              logit = out_classes->data.f[i * SSD_NUM_CLASSES + c];
            }

          /* Sigmoid: 1 / (1 + exp(-logit)) */

          float score = 1.0f / (1.0f + fast_exp(-logit));
          if (score > best_score)
            {
              best_score = score;
              best_class = c;
            }
        }

      /* Filter: person class (COCO class 1) and above threshold */

      if (best_class != 1 || best_score < DETECT_THRESHOLD)
        {
          continue;
        }

      /* Read decoded box coordinates */

      const float *box = &decoded_boxes[i * 4];
      person_boxes[person_count].ymin = box[0];
      person_boxes[person_count].xmin = box[1];
      person_boxes[person_count].ymax = box[2];
      person_boxes[person_count].xmax = box[3];
      person_boxes[person_count].score = best_score;
      person_boxes[person_count].class_id = 1; /* person */
      person_count++;
    }

  /* Apply NMS */

  result->num_detections = nms_filter(person_boxes, person_count,
                                       NMS_IOU_THRESHOLD,
                                       NMS_MAX_DETECTIONS);
  for (int i = 0; i < result->num_detections; i++)
    {
      result->boxes[i] = person_boxes[i];
    }

  return 0;
}

void tflite_deinit(void)
{
  g_interpreter = nullptr;
  g_model = nullptr;

  if (g_arena)
    {
      delete[] g_arena;
      g_arena = nullptr;
    }

  if (g_model_data)
    {
      delete[] g_model_data;
      g_model_data = nullptr;
    }

  printf("TFLITE: deinitialized\n");
}

