int tflite_init(const char *model_path, int arena_size)
{
  /* Load model from filesystem using C file I/O */

  FILE *fp = fopen(model_path, "rb");
  if (!fp)
    {
      printf("TFLITE: failed to open model: %s\n", model_path);
      return -1;
    }

  fseek(fp, 0, SEEK_END);
  size_t model_size = ftell(fp);
  fseek(fp, 0, SEEK_SET);

  g_model_data = new (std::nothrow) uint8_t[model_size];
  if (!g_model_data)
    {
      printf("TFLITE: failed to alloc model buf (%zu bytes)\n", model_size);
      fclose(fp);
      return -1;
    }

  size_t bytes_read = fread(g_model_data, 1, model_size, fp);
  fclose(fp);

  if (bytes_read != model_size)
    {
      printf("TFLITE: read error: %zu / %zu bytes\n", bytes_read, model_size);
      delete[] g_model_data;
      g_model_data = nullptr;
      return -1;
    }

