/* GCC 10.3 compatibility workaround for NuttX libcxx headers.
 * Redefine problematic builtins as macros.
 */

#ifndef __GCC_COMPAT_H
#define __GCC_COMPAT_H

/* Disable problematic type traits builtins */

#define __is_nothrow_assignable(...) true
#define __is_nothrow_constructible(...) true

/* Workaround for bit_cast issue */

namespace std {
namespace __1 {
template<typename _ToType, typename _FromType>
inline constexpr _ToType __bit_cast_workaround(const _FromType& __from) {
    _ToType __to;
    __builtin_memcpy(&__to, &__from, sizeof(_ToType));
    return __to;
}
}
}

#define __builtin_bit_cast std::__1::__bit_cast_workaround

#endif /* __GCC_COMPAT_H */

